// ===== 3. Update User Status (Block/Unblock) =====
const updateUserStatus = async (
  userId: string,
  data: IUpdateUserStatus
) => {
  try {
    const { status } = data;

    // Check user exists
    const user = await prisma.user.findUnique({
      where: { id: userId },
    });

    if (!user) {
      throw new AppError(httpStatus.NOT_FOUND, "User not found");
    }

    if (user.isDeleted) {
      throw new AppError(
        httpStatus.BAD_REQUEST,
        "Cannot update status of deleted user"
      );
    }

    // Prevent admin from blocking other admins
    if (user.role === Role.ADMIN) {
      throw new AppError(
        httpStatus.FORBIDDEN,
        "Cannot block/unblock admin users"
      );
    }

    // Update status
    const updatedUser = await prisma.user.update({
      where: { id: userId },
      data: {
        status: status as UserStatus,
      },
      select: {
        id: true,
        name: true,
        email: true,
        role: true,
        status: true,
        updatedAt: true,
      },
    });

    return updatedUser;
  } catch (error: any) {
    if (error instanceof AppError) throw error;
    throw new AppError(httpStatus.INTERNAL_SERVER_ERROR, error.message);
  }
};

// ===== 4. Delete User (Soft Delete) =====
const deleteUser = async (userId: string) => {
  try {
    // Check user exists
    const user = await prisma.user.findUnique({
      where: { id: userId },
    });

    if (!user) {
      throw new AppError(httpStatus.NOT_FOUND, "User not found");
    }

    if (user.isDeleted) {
      throw new AppError(httpStatus.BAD_REQUEST, "User already deleted");
    }

    // Prevent admin from deleting other admins
    if (user.role === Role.ADMIN) {
      throw new AppError(httpStatus.FORBIDDEN, "Cannot delete admin users");
    }

    // Soft delete
    const deletedUser = await prisma.user.update({
      where: { id: userId },
      data: {
        isDeleted: true,
        status: UserStatus.DELETED,
        deletedAt: new Date(),
      },
      select: {
        id: true,
        name: true,
        email: true,
        role: true,
        status: true,
        isDeleted: true,
        deletedAt: true,
      },
    });

    return deletedUser;
  } catch (error: any) {
    if (error instanceof AppError) throw error;
    throw new AppError(httpStatus.INTERNAL_SERVER_ERROR, error.message);
  }
};

