import {
  IAdminBookingQuery,
  IAdminPaymentQuery,
} from "./admin.interface";

// =============================================
// ===== 1. Get All Bookings (Admin) =====
// =============================================
const getAllBookings = async (query: IAdminBookingQuery) => {
  try {
    const limit = query.limit ? Number(query.limit) : 10;
    const page = query.page ? Number(query.page) : 1;
    const skip = (page - 1) * limit;
    const sortBy = query.sortBy || "createdAt";
    const sortOrder = query.sortOrder || "desc";

    const andConditions: any[] = [];

    // Filter by booking status
    if (query.status) {
      andConditions.push({ status: query.status });
    }

    // Filter by payment status
    if (query.paymentStatus) {
      andConditions.push({
        payment: { status: query.paymentStatus },
      });
    }

    // Filter by tourist email
    if (query.touristEmail) {
      andConditions.push({
        tourist: {
          user: {
            email: { contains: query.touristEmail, mode: "insensitive" },
          },
        },
      });
    }

    // Filter by guide email
    if (query.guideEmail) {
      andConditions.push({
        guide: {
          user: {
            email: { contains: query.guideEmail, mode: "insensitive" },
          },
        },
      });
    }

    // Filter by package
    if (query.packageId) {
      andConditions.push({ packageId: query.packageId });
    }

    // Filter by date range (tourDate)
    if (query.startDate || query.endDate) {
      const dateFilter: any = {};
      if (query.startDate) dateFilter.gte = new Date(query.startDate);
      if (query.endDate) dateFilter.lte = new Date(query.endDate);
      andConditions.push({ tourDate: dateFilter });
    }

    const sortField = ["createdAt", "tourDate", "totalPrice"].includes(sortBy)
      ? sortBy
      : "createdAt";

    const bookings = await prisma.booking.findMany({
      where: andConditions.length > 0 ? { AND: andConditions } : {},
      take: limit,
      skip,
      orderBy: { [sortField]: sortOrder as "asc" | "desc" },
      include: {
        tourist: {
          include: {
            user: {
              select: {
                id: true,
                name: true,
                email: true,
                imageUrl: true,
              },
            },
          },
        },
        guide: {
          include: {
            user: {
              select: {
                id: true,
                name: true,
                email: true,
                imageUrl: true,
              },
            },
          },
        },
        package: {
          select: {
            id: true,
            title: true,
            meetingPoint: true,
            pricePerPerson: true,
          },
        },
        payment: {
          select: {
            id: true,
            amount: true,
            status: true,
            bKashTrxId: true,
            guideEarning: true,
            commissionFee: true,
            platformFee: true,
            paidAt: true,
            refundedAt: true,
            refundReason: true,
          },
        },
      },
    });

    const total = await prisma.booking.count({
      where: andConditions.length > 0 ? { AND: andConditions } : {},
    });

    return {
      data: bookings,
      meta: {
        page,
        limit,
        total,
        totalPages: Math.ceil(total / limit),
      },
    };
  } catch (error: any) {
    if (error instanceof AppError) throw error;
    throw new AppError(httpStatus.INTERNAL_SERVER_ERROR, error.message);
  }
};

// =============================================
// ===== 2. Get Single Booking Details (Admin) =====
// =============================================
const getBookingDetails = async (bookingId: string) => {
  try {
    const booking = await prisma.booking.findUnique({
      where: { id: bookingId },
      include: {
        tourist: {
          include: {
            user: {
              select: {
                id: true,
                name: true,
                email: true,
                imageUrl: true,
                status: true,
                emailVerified: true,
              },
            },
          },
        },
        guide: {
          include: {
            user: {
              select: {
                id: true,
                name: true,
                email: true,
                imageUrl: true,
                status: true,
              },
            },
          },
        },
        package: {
          include: {
            guide: {
              include: {
                user: {
                  select: {
                    id: true,
                    name: true,
                    email: true,
                    imageUrl: true,
                  },
                },
              },
            },
          },
        },
        payment: true,          // ← Full payment data
        review: true,           // ← Review if exists
        complaint: true,        // ← Complaint if exists
      },
    });

    if (!booking) {
      throw new AppError(httpStatus.NOT_FOUND, "Booking not found");
    }

    return booking;
  } catch (error: any) {
    if (error instanceof AppError) throw error;
    throw new AppError(httpStatus.INTERNAL_SERVER_ERROR, error.message);
  }
};

// =============================================
// ===== 3. Get All Payments (Admin) =====
// =============================================
const getAllPayments = async (query: IAdminPaymentQuery) => {
  try {
    const limit = query.limit ? Number(query.limit) : 10;
    const page = query.page ? Number(query.page) : 1;
    const skip = (page - 1) * limit;
    const sortBy = query.sortBy || "createdAt";
    const sortOrder = query.sortOrder || "desc";

    const andConditions: any[] = [];

    // Filter by payment status
    if (query.status) {
      andConditions.push({ status: query.status });
    }

    // Filter by payment method
    if (query.method) {
      andConditions.push({ paymentMethod: query.method });
    }

    // Filter by date range (createdAt)
    if (query.startDate || query.endDate) {
      const dateFilter: any = {};
      if (query.startDate) dateFilter.gte = new Date(query.startDate);
      if (query.endDate) dateFilter.lte = new Date(query.endDate);
      andConditions.push({ createdAt: dateFilter });
    }

    const sortField = ["createdAt", "amount", "paidAt"].includes(sortBy)
      ? sortBy
      : "createdAt";

    const payments = await prisma.payment.findMany({
      where: andConditions.length > 0 ? { AND: andConditions } : {},
      take: limit,
      skip,
      orderBy: { [sortField]: sortOrder as "asc" | "desc" },
      include: {
        booking: {
          select: {
            id: true,
            bookingReference: true,
            tourDate: true,
            numberOfPeople: true,
            totalPrice: true,
            status: true,
            tourist: {
              include: {
                user: {
                  select: {
                    id: true,
                    name: true,
                    email: true,
                    imageUrl: true,
                  },
                },
              },
            },
            guide: {
              include: {
                user: {
                  select: {
                    id: true,
                    name: true,
                    email: true,
                    imageUrl: true,
                  },
                },
              },
            },
          },
        },
      },
    });

    const total = await prisma.payment.count({
      where: andConditions.length > 0 ? { AND: andConditions } : {},
    });

    // Calculate statistics
    const stats = await prisma.payment.groupBy({
      by: ["status"],
      _count: true,
      _sum: {
        amount: true,
        guideEarning: true,
        commissionFee: true,
        platformFee: true,
      },
    });

    return {
      data: payments,
      stats,
      meta: {
        page,
        limit,
        total,
        totalPages: Math.ceil(total / limit),
      },
    };
  } catch (error: any) {
    if (error instanceof AppError) throw error;
    throw new AppError(httpStatus.INTERNAL_SERVER_ERROR, error.message);
  }
};




export const AdminService = {
  getAllTourists,
  getAllGuides,
  updateUserStatus,
  deleteUser,
  getUserDetails,

    getAllBookings,
  getBookingDetails,
  getAllPayments,
};